pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, address newOwner) public {
        // Ensure the actor is not the current owner, so we test the onlyOwner check
        vm.assume(actor != c.owner());
        // The new owner must differ from the current one so a change is observable
        vm.assume(newOwner != c.owner());

        address ownerBefore = c.owner();
        vm.prank(actor);
        c.setOwner(newOwner);

        // The general rule: a non-owner call must not change the owner
        assertTrue(c.owner() == ownerBefore);
    }
}

