import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _owner, address _caller) public {
        vm.assume(_owner != _caller);
        address originalOwner = c.owner();
        vm.prank(_caller);
        bool ok;
        try c.setOwner(_owner) returns (bool success) {
            ok = success;
        } catch {
            ok = false;
        }
        address newOwner = c.owner();
        assertTrue(
            (ok && newOwner == _owner) || (!ok && newOwner == originalOwner)
        );
    }
}

