// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        // Ensure the caller is the current owner
        vm.prank(address(this));
        c = new C(); // reset to ensure clean state (first owner is address(this))
        vm.prank(address(this));
        // Call setOwner as the owner
        (bool success, bytes memory retdata) = address(c).call(abi.encodeWithSignature("setOwner(address)", newOwner));
        // If the call does not revert, we check the return value
        if (success) {
            bool ret = abi.decode(retdata, (bool));
            assertTrue(ret);
        }
    }
}
